import json,pathlib,hashlib,urllib.request,urllib.parse,pypdf
from shapely.geometry import Polygon
P=pathlib.Path(__file__).parent
# Pixel vertices manually traced on the retained 8x render. This is a map-symbol footprint, not survey geometry.
px=[[282,119],[315,119],[315,91],[354,91],[354,119],[389,119],[387,252],[280,252]]
pg=pypdf.PdfReader(P/'usgs-peninsula-1994.pdf').pages[0];H=float(pg.mediabox.height);L=pg['/LGIDict'][0];ctm=list(map(float,L['/CTM']))
poly=Polygon([(425+x/8,H-(85+y/8))for x,y in px]);center=[poly.centroid.x,poly.centroid.y];points=[center]+[list(x)for x in poly.exterior.coords]
a,b,c,d,e,f=ctm;geo=[{'x':a*x+c*y+e,'y':b*x+d*y+f}for x,y in points]
wkt=json.loads((P/'richfield-geopdf-reprojection-metadata.json').read_text())['sourceWkt']
u='https://utility.arcgisonline.com/ArcGIS/rest/services/Geometry/GeometryServer/project?'+urllib.parse.urlencode({'inSR':json.dumps({'wkt':wkt}),'outSR':4326,'geometries':json.dumps({'geometryType':'esriGeometryPoint','geometries':geo}),'f':'json'})
with urllib.request.urlopen(u,timeout=60)as r:body=r.read()
(P/'richfield-roof-reprojection.json').write_bytes(body);r=json.loads(body);p=r['geometries'][0]
o={'arenaId':'cle-richfield','latitude':p['y'],'longitude':p['x'],'status':'primary-usgs-historical-roof-map-symbol-centroid-derived','pointMeaning':'area centroid of manually traced original 1994 USGS map building symbol; mapped site point, not surveyed court center','sourceUrl':'https://prd-tnm.s3.amazonaws.com/StagedProducts/Maps/HistoricalTopo/PDF/OH/24000/OH_Peninsula_228030_1994_24000_geo.pdf','sourcePath':'usgs-peninsula-1994.pdf','sourceBodySha256':hashlib.sha256((P/'usgs-peninsula-1994.pdf').read_bytes()).hexdigest(),'bodySha256':hashlib.sha256((P/'usgs-peninsula-1994.pdf').read_bytes()).hexdigest(),'renderPath':'usgs-richfield-building-detail.png','renderClipPdfTopLeft':[425,85,490,130],'renderScale':8,'tracedImageVertices':px,'pdfVertices':list(map(list,poly.exterior.coords)),'pdfCentroid':center,'mapCTM':ctm,'sourceWkt':wkt,'projectionRequestUrl':u,'projectionResponsePath':'richfield-roof-reprojection.json','projectionResponseSha256':hashlib.sha256(body).hexdigest(),'transformedVerticesWgs84':r['geometries'][1:],'derivation':'shoelace polygon area centroid in PDF coordinate plane; GeoPDF CTM to map meters; NAD27 Lambert Conformal Conic 2SP to WGS84 via original ArcGIS GeometryServer. Four retained neatline corner controls in richfield-geopdf-reprojection-metadata.json reproduce quad limits plus datum shift.','identityPrimarySources':['https://home.nps.gov/cuva/learn/historyculture/former-coliseum-property.htm','https://www.nps.gov/cuva/learn/kidsyouth/grasslands.htm'],'uncertainty':'Manually traced printed building symbol at 1:24000; practical accuracy tens of meters. NPS historical aerial corroborates physical building and surrounding parking/road layout. GeoNames point lies close to traced roof; southern candidate was not adopted.'}
(P/'richfield-usgs-derived-coordinate.json').write_text(json.dumps(o,indent=2)+'\n');print(json.dumps({k:o[k]for k in ['latitude','longitude','sourceBodySha256']}))
